<?php
namespace App\Jobs;use App\Domain\Workflow\{StepExecutionStatus,WorkflowExecutionStatus};use App\Models\{DeadLetter,ExecutionAttempt,StepExecution,WorkflowExecution};use App\Services\WorkflowQueue;use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\{InteractsWithQueue,SerializesModels};use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
final class RecoverStalledSteps implements ShouldQueue{use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public function handle(WorkflowQueue $queues):void{StepExecution::where('status',StepExecutionStatus::Running->value)->where('started_at','<',now()->subMinutes(5))->orderBy('started_at')->chunkById(100,function($steps)use($queues){foreach($steps as $candidate){$execution=DB::transaction(function()use($candidate){$s=StepExecution::with('workflowStep','execution.version.workflow')->lockForUpdate()->find($candidate->id);if(!$s||$s->status!==StepExecutionStatus::Running||!$s->started_at?->lt(now()->subMinutes(5)))return null;ExecutionAttempt::where('step_execution_id',$s->id)->where('status','running')->update(['status'=>'failed','finished_at'=>now(),'error_metadata_json'=>['classification'=>'worker_lost','message'=>'Worker lease exceeded stale threshold']]);$max=max(1,(int)($s->workflowStep->retry_policy_json['max_attempts']??3));if($s->attempt_count<$max){$s->update(['status'=>StepExecutionStatus::Pending,'error_class'=>'worker_lost','error_message'=>'Recovered stale running step']);return $s->execution;} $s->update(['status'=>StepExecutionStatus::Failed,'completed_at'=>now(),'dead_lettered_at'=>now(),'error_class'=>'worker_lost','error_message'=>'Worker lost after final permitted attempt']);DeadLetter::create(['workflow_execution_id'=>$s->workflow_execution_id,'step_execution_id'=>$s->id,'failure_code'=>'worker_lost','error_metadata_json'=>['attempts'=>$s->attempt_count],'created_at'=>now()]);$s->execution->update(['status'=>WorkflowExecutionStatus::Failed,'failure_code'=>'worker_lost','completed_at'=>now()]);return null;},3);if($execution)ExecuteWorkflowStep::dispatch($execution->id)->onQueue($queues->name($execution->version->workflow));}});}}
